"""Verdicts de HA1b, HA1 (version 4) et HB1 à HB7, appliquant les règles préinscrites ; résultats RB1 (précédent v1 et actuel v3 côte à côte). Idempotent."""
import sys, pathlib
sys.path.insert(0, str(pathlib.Path(__file__).resolve().parents[1] / "src"))
import tp2_journal as J
def last(i): return [e for e in J.entries() if e["id"] == i][-1]
def verdict(i, statut, preuve, note="", just="Verdict établi avec la règle de décision préinscrite (voir la version précédente)."):
    l = last(i)
    if l["statut"] == "préinscrite" or (i == "HA1" and l["version"] == 3): J.add(i, "hypothese", l["titre"], l["texte"], justification=just, statut=statut, preuve=preuve, note=note)
F = "artifacts/results/v3/A_apparie_HA1b.csv ; A_HA1_reanalyse_non_appariee.csv ; B_resume.csv ; B_tests_pairs.csv ; B_nemenyi_tous.csv ; B_repli.csv"
verdict("HA1b", "confirmée", "Écart H moins G (macro-F1 du palier A, mêmes logs de test, 25 plis) : centroïde +0,294 [0,261 ; 0,323] ; kNN +0,521 [0,497 ; 0,543] ; régression logistique +0,483 [0,461 ; 0,504] ; Naive Bayes +0,430 [0,404 ; 0,454] ; SVM caractères +0,477 [0,453 ; 0,502] ; SVM mots +0,474 [0,457 ; 0,491]. Les six dépassent 0,20 ; plus petit écart observé sur un pli : +0,117 (centroïde). Wilcoxon sur 25 plis, p ajusté de Holm < 1e-6, Cliff delta = 1 pour les six. Sans fuite (G), le SVM mots donne 0,504, soit le score de P2 (0,503) : le montage reproduit bien P2.  Fichiers : " + F,
        note="Plus un modèle mémorise, plus la fuite le gonfle : le kNN passe de 0,41 à 0,93 (+0,52), le centroïde, qui résume chaque classe par un seul centre, ne gagne que +0,29.")
verdict("HA1", "confirmée", "Deux preuves indépendantes de l'écart entre découpage au hasard et par groupes : (1) HA1b, montage apparié sur les mêmes logs de test (voir HA1b) ; (2) réanalyse non appariée des anciennes données par le test de Mann-Whitney : pour les six modèles, le plus petit score sous P0 dépasse le plus grand sous P2 (écart de 0,47 à 0,55, Cliff delta = 1, p ajusté < 1e-6).  Fichiers : " + F,
        note="Version 4. La version 2 (« confirmée », appariement injustifié) et la version 3 (« non tranchée ») restent dans l'historique ; le verdict final repose sur HA1b et la réanalyse non appariée, pas sur l'appariement initial.", just="Rejouée comme demandé par l'étudiant : l'appariement de la version 2 n'était pas justifié ; les deux nouvelles analyses n'en dépendent pas.")
verdict("HB1", "confirmée", "Macro-F1 des classes (palier A), hiérarchique moins plat (régression logistique) : −0,014, IC 95 % [−0,024 ; −0,004], p Holm 0,037. La hiérarchie n'améliore pas : elle est même très légèrement moins bonne (significatif après Holm), mais |écart| = 0,014 < 0,03, donc la règle (« ne diffère pas, ou |écart| < 0,03 ») est satisfaite.  Fichiers : " + F,
        note="Précédent (notebook v1, étape 7.3, test v1 consommé, palier A) : plat 0,4832 contre hiérarchique 0,5153, écart +0,023, IC [−0,010 ; +0,047], non tranchée. Actuel (v3, développement, P2) : plat 0,4947 contre hiérarchique 0,4806, écart −0,014. Le signe de l'écart diffère, comme le notebook v1 le soupçonnait (H1 : signe qui change) ; les deux sont proches de zéro. Les deux séries sont conservées.")
verdict("HB2", "réfutée", "F1 des familles (famille déduite de la classe prédite), hiérarchique moins plat : +0,013, IC 95 % [+0,002 ; +0,024], p Holm 0,055. Le gain n'est ni d'au moins 0,03 ni significatif après Holm ; l'IC exclut un gain de 0,03.  Fichiers : " + F,
        note="La tête « famille » directe est un peu meilleure (0,706 contre 0,693 en F1 famille moyen) mais pas assez pour la règle.")
verdict("HB3", "réfutée", "Distance moyenne d'erreur dans l'arbre, hiérarchique moins plat : −0,001, IC [−0,022 ; +0,020], p Holm 0,94. Aucune réduction de la gravité des erreurs.  Fichiers : " + F)
verdict("HB4", "non tranchée", "k-means par classe à 10 prototypes moins centroïde unique : +0,026, IC 95 % [−0,000 ; +0,051], p Holm 0,067. Le critère (p Holm < 0,05) n'est pas atteint, mais l'IC ne se distingue de zéro que par un cheveu et n'exclut pas un gain jusqu'à 0,05.  Fichiers : " + F,
        note="Règle de classement des verdicts : « réfutée » seulement si l'IC exclut un effet notable (cas de HA6, HB2, HB3) ; ici l'effet reste plausible, donc « non tranchée ». À rejouer avec plus de graines ou une autre dimension SVD (itération de la phase 2).")
verdict("HB5", "confirmée", "Gabarits-prototypes moins centroïde : +0,044, IC [+0,020 ; +0,069], p Holm 0,007 ; SVM mots moins gabarits-prototypes : +0,054, IC [+0,035 ; +0,073], p Holm 8e-5 (>= 0,03). Les gabarits-prototypes (0,449) battent le centroïde (0,406) mais pas le SVM (0,503).  Fichiers : " + F,
        note="Notre proposition F3 donne le meilleur résultat des méthodes de ressemblance après le k-means global à 150 groupes, sans être entraînée de façon discriminante.")
verdict("HB6", "non tranchée", "Écart SVM mots moins chaque clustering global (macro-F1 palier A) : k-means 60 groupes +0,096 ; Birch +0,111 ; DBSCAN +0,092 ; HDBSCAN +0,086 ; k-means 150 groupes +0,049 [0,026 ; 0,072]. Les cinq sont significativement inférieurs au SVM (p Holm < 5e-4), mais k-means 150 manque le seuil préinscrit de 0,05 de 0,001 et son IC contient 0,05.  Fichiers : " + F,
        note="L'essentiel de l'hypothèse (aucun clustering global n'atteint le SVM) est confirmé ; le seuil quantitatif ne l'est pas pour un des cinq. Constat additionnel : k-means à 150 groupes (0,454) fait mieux que k-means à 60 groupes (0,408) : des groupes plus fins, proches du nombre de gabarits, aident, ce qui va dans le sens des gabarits-prototypes.")
verdict("HB7", "confirmée", "Friedman sur kNN (k = 15), k-means par classe (3 et 10), mélange gaussien, Ward et gabarits-prototypes : p = 0,23 ; différence critique de Nemenyi 1,51 rang ; les cinq méthodes sont à moins de 1,12 rang du kNN : indiscernables.  Fichiers : " + F,
        note="Réserve : les rangs moyens dépendent de l'ensemble des méthodes comparées (Benavoli et al. 2016, S13 dans sources_v3_stats_repro.md). Dans le Friedman sur les 19 sorties, la différence critique monte à 5,60 rangs et kNN (10,2) et gabarits-prototypes (7,6) restent aussi indiscernables.")
if not J.exists("RB1"):
    J.add("RB1", "resultat", "Bloc B : macro-F1 du palier A sous P2 (précédent v1 et actuel v3)",
          "**Actuel (v3, développement, P2, 25 plis) :** SVM mots 0,503 ; régression logistique 0,495 ; hiérarchique 0,481 ; k-means global 150 groupes 0,454 ; gabarits-prototypes 0,449 ; k-means par classe 3 prototypes 0,441 ; Ward 0,439 ; Naive Bayes 0,434 ; k-means par classe 10 prototypes 0,431 ; kNN 15 0,423 ; mélange gaussien 0,422 ; HDBSCAN (sans rejet) 0,418 ; DBSCAN (sans rejet) 0,411 ; kNN 5 0,410 ; k-means 60 groupes 0,408 ; centroïde 0,406 ; Birch 0,392 ; HDBSCAN avec rejet 0,110 ; DBSCAN avec rejet 0,089 (les deux rejettent 82 à 85 % des logs de test).  Repli sur la famille (seuil 0,5) : répond au niveau de la classe pour 72,9 % des logs, justesse de classe sur ces logs 61,7 % ; justesse de famille 71,1 % avec ou sans repli.  **Précédent (notebook v1, étape 7.3, test v1 consommé) :** TF-IDF plat 0,4832, hiérarchique 0,5153 (palier A) ; Skip-gram 0,4027 et 0,4635 (validation).  Les deux séries sont conservées ; aucun modèle ne dépasse 0,51 dans l'une ou l'autre.",
          justification="Le plafond d'environ 0,50 se retrouve avec un protocole indépendant et 19 méthodes de natures très différentes : le goulot est la représentation (mots) face à des gabarits nouveaux, pas le choix du classifieur. C'est la motivation des pistes de la phase 2 (marqueurs typés, combinaison mots, lettres, Transformer).", preuve=F, note="Cas particulier : les sorties avec rejet de DBSCAN et HDBSCAN comptent un rejet comme une erreur ; elles mesurent surtout que les logs de nouveaux gabarits sont loin de tous les points d'entraînement (utile au bloc C).")
print(J.render())
